"""Build the vendored SDL 3.4.16 (zlib licence, startup/third_party/SDL3-3.4.16) as a native static archive
holding only what host gamepad input needs on Windows.

Source: https://github.com/libsdl-org/SDL/releases/download/release-3.4.16/SDL3-3.4.16.zip (gpg-verified with
its .sig; the release builder pins the zip's SHA-256). No CMake: the C sources below are compiled directly with zig cc against SDL's
Windows config (include/build_config/SDL_build_config_windows.h) plus an overlay (sdl-build/config/
SDL_build_config.h, written here) that disables every subsystem the runtime does not use:

  kept      core init/hints/properties/log, events, joystick + gamepad (HIDAPI drivers for PS3/PS4/PS5/Switch/
            Switch 2/Xbox 360/Xbox One/GIP/Steam/..., XInput, DirectInput, RawInput, virtual joysticks),
            sensors (gamepad gyro/accel come through the joystick drivers; the Windows sensor API backend is
            replaced by the dummy driver), rumble/trigger rumble/LED (joystick-level, SDL_RumbleGamepad),
            threads, timers, stdlib, cpuinfo, loadso, iostream, time.
  disabled  video, GPU, audio, camera, haptic (force-feedback devices; gamepad rumble does not use it),
            power, dialog, tray, GameInput and Windows.Gaming.Input (headers absent from zig's mingw-w64).
  dynapi    off (-D__RESHARPER__ is the one switch SDL_dynapi.h honours without editing the source): no
            SDL3_DYNAMIC_API environment override can load another SDL into the game process.

Output: startup/third_party/sdl-build/libSDL3.a (rebuilt only if missing or the source list/flags change), plus
libtotk_input.a from startup/host_input_sdl.c (the runtime's SDL backend) when that file exists.
compile_cached_fast.py / compile_cached.py append link_args() to the runtime DLL link; tests link directly.
Like build_opus.py the archive path goes to stderr: stdout of the callers is a JSON build report.
"""
import hashlib,json,subprocess,sys,concurrent.futures
from pathlib import Path

HERE=Path(__file__).resolve().parent
VERSION='3.4.16'
SRC=HERE/f'SDL3-{VERSION}'
OUT=HERE/'sdl-build'
CONFIG=OUT/'config'
ZIG=HERE.parent.parent/'tools/zig-x86_64-windows-0.16.0/zig.exe'
SHIM=HERE.parent/'host_input_sdl.c'
JOBS=2   # coordinator limit: at most 2 concurrent compile jobs

OVERLAY='''/* GENERATED by startup/third_party/build_sdl.py: SDL's Windows config minus every subsystem the TOTK
 * runtime does not use (gamepad input only). Found before include/build_config by the -I order. */
#ifndef TOTK_SDL_BUILD_CONFIG_H
#define TOTK_SDL_BUILD_CONFIG_H
#include "SDL_build_config_windows.h"
#undef HAVE_GAMEINPUT_H
#undef SDL_JOYSTICK_GAMEINPUT
#undef HAVE_WINDOWS_GAMING_INPUT_H
#undef SDL_JOYSTICK_WGI
#undef HAVE_SENSORSAPI_H
#undef SDL_SENSOR_WINDOWS
#define SDL_SENSOR_DUMMY 1
#undef SDL_HAPTIC_DINPUT
#define SDL_HAPTIC_DISABLED 1
#undef SDL_AUDIO_DRIVER_WASAPI
#undef SDL_AUDIO_DRIVER_DSOUND
#undef SDL_AUDIO_DRIVER_DISK
#undef SDL_AUDIO_DRIVER_DUMMY
#define SDL_AUDIO_DISABLED 1
#undef SDL_VIDEO_DRIVER_DUMMY
#undef SDL_VIDEO_DRIVER_OFFSCREEN
#undef SDL_VIDEO_DRIVER_WINDOWS
#undef SDL_VIDEO_RENDER_D3D
#undef SDL_VIDEO_RENDER_D3D11
#undef SDL_VIDEO_RENDER_D3D12
#undef SDL_VIDEO_OPENGL
#undef SDL_VIDEO_OPENGL_WGL
#undef SDL_VIDEO_RENDER_OGL
#undef SDL_VIDEO_RENDER_OGL_ES2
#undef SDL_VIDEO_OPENGL_ES2
#undef SDL_VIDEO_OPENGL_EGL
#undef SDL_VIDEO_VULKAN
#undef SDL_VIDEO_RENDER_VULKAN
#undef SDL_VIDEO_RENDER_GPU
#undef SDL_GPU_D3D11
#undef SDL_GPU_D3D12
#undef SDL_GPU_VULKAN
#define SDL_VIDEO_DISABLED 1
#define SDL_RENDER_DISABLED 1
#define SDL_GPU_DISABLED 1
#undef SDL_CAMERA_DRIVER_MEDIAFOUNDATION
#undef SDL_CAMERA_DRIVER_DUMMY
#define SDL_CAMERA_DISABLED 1
#undef SDL_POWER_WINDOWS
#define SDL_POWER_DISABLED 1
#define SDL_DIALOG_DISABLED 1
#define SDL_TRAY_DUMMY 1
#undef SDL_PROCESS_WINDOWS
#define SDL_PROCESS_DUMMY 1
#endif
'''

def sources():
    s=lambda *names:[f'src/{n}' for n in names]
    files=s('SDL.c','SDL_assert.c','SDL_error.c','SDL_guid.c','SDL_hashtable.c','SDL_hints.c','SDL_list.c','SDL_log.c',
            'SDL_properties.c','SDL_utils.c')
    files+=s('atomic/SDL_atomic.c','atomic/SDL_spinlock.c','cpuinfo/SDL_cpuinfo.c','dynapi/SDL_dynapi.c',
             'core/windows/SDL_windows.c','core/windows/SDL_hid.c','core/windows/SDL_xinput.c',
             'loadso/windows/SDL_sysloadso.c','io/SDL_iostream.c',
             'time/SDL_time.c','time/windows/SDL_systime.c','timer/SDL_timer.c','timer/windows/SDL_systimer.c',
             'thread/SDL_thread.c','thread/generic/SDL_syscond.c','thread/generic/SDL_sysrwlock.c',
             'thread/windows/SDL_syscond_cv.c','thread/windows/SDL_sysmutex.c','thread/windows/SDL_sysrwlock_srw.c',
             'thread/windows/SDL_syssem.c','thread/windows/SDL_systhread.c','thread/windows/SDL_systls.c',
             'sensor/SDL_sensor.c','sensor/dummy/SDL_dummysensor.c','hidapi/SDL_hidapi.c')
    files+=sorted(str(p.relative_to(SRC).as_posix()) for p in (SRC/'src/stdlib').glob('*.c'))
    files+=sorted(str(p.relative_to(SRC).as_posix()) for p in (SRC/'src/events').glob('*.c'))
    # Core pieces SDL.c/SDL_events.c/SDL_properties.c always reference (CMake compiles them in every
    # configuration): the video core and render core (surfaces, pixel formats, window bookkeeping; no
    # video or render driver is enabled, so SDL_INIT_VIDEO fails), filesystem, async I/O (generic), tray bookkeeping, SDL's libm.
    files+=sorted(str(p.relative_to(SRC).as_posix()) for p in (SRC/'src/video').glob('*.c'))
    files+=s('video/yuv2rgb/yuv_rgb_std.c','video/yuv2rgb/yuv_rgb_sse.c','filesystem/SDL_filesystem.c',
             'filesystem/windows/SDL_sysfilesystem.c','filesystem/windows/SDL_sysfsops.c','io/SDL_asyncio.c',
             'io/generic/SDL_asyncio_generic.c','io/windows/SDL_asyncio_windows_ioring.c','tray/SDL_tray_utils.c',
             'tray/dummy/SDL_tray.c','main/SDL_main_callbacks.c')
    files+=sorted(str(p.relative_to(SRC).as_posix()) for p in (SRC/'src/render').glob('*.c'))
    files+=sorted(str(p.relative_to(SRC).as_posix()) for p in (SRC/'src/libm').glob('*.c'))
    for d in ('joystick','joystick/hidapi','joystick/windows','joystick/virtual'):
        files+=sorted(str(p.relative_to(SRC).as_posix()) for p in (SRC/'src'/d).glob('*.c'))
    return files

FLAGS=['-target','x86_64-windows-gnu','-std=gnu11','-O2','-w','-fno-sanitize=undefined','-D__RESHARPER__',
       '-DSDL_STATIC_LIB','-DSDL_BUILD_MAJOR_VERSION=3','-DSDL_BUILD_MINOR_VERSION=4','-DSDL_BUILD_MICRO_VERSION=16',
       '-DNDEBUG']

def include_flags():
    return [f'-I{CONFIG.as_posix()}',f'-I{(SRC/"include").as_posix()}',f'-I{(SRC/"include/build_config").as_posix()}',
            f'-I{(SRC/"src").as_posix()}']

def _archive(name,files,flags,root):
    # The vendored SDL tree is immutable (a version bump changes SRC); the shim is keyed by its content.
    content=[hashlib.sha256((root/f).read_bytes()).hexdigest() if root!=SRC else '' for f in files]
    key=hashlib.sha256(json.dumps([files,flags,OVERLAY,content]).encode()).hexdigest()
    archive=OUT/name;stamp=archive.with_suffix('.key')
    if archive.exists() and stamp.exists() and stamp.read_text()==key:return archive
    objdir=OUT/(archive.stem+'-obj');objdir.mkdir(parents=True,exist_ok=True)
    unit_key=hashlib.sha256(json.dumps([flags,OVERLAY]).encode()).hexdigest()[:12]
    def compile_one(item):
        rel,digest=item
        obj=objdir/(rel.replace('/','_').replace(':','_')[:-2]+f'-{unit_key}{digest[:8]}.o')
        if obj.exists():return obj   # objects are written via a temporary name, so an existing one is complete
        temporary=obj.with_suffix('.tmp')
        r=subprocess.run([str(ZIG),'cc',*flags,'-c',str(root/rel),'-o',str(temporary)],capture_output=True,text=True)
        if r.returncode:raise RuntimeError(f'{rel}:\n{r.stderr}')
        temporary.replace(obj);return obj
    files=list(zip(files,content))
    with concurrent.futures.ThreadPoolExecutor(JOBS) as pool:objs=list(pool.map(compile_one,files))
    if archive.exists():archive.unlink()
    subprocess.run([str(ZIG),'ar','rcs',str(archive),*map(str,objs)],check=True)
    stamp.write_text(key);return archive

def main():
    OUT.mkdir(exist_ok=True);CONFIG.mkdir(exist_ok=True)
    cfg=CONFIG/'SDL_build_config.h'
    if not cfg.exists() or cfg.read_text()!=OVERLAY:cfg.write_text(OVERLAY)
    archive=_archive('libSDL3.a',sources(),FLAGS+include_flags(),SRC)
    print(archive,file=sys.stderr)
    if SHIM.exists():
        shim=_archive('libtotk_input.a',[SHIM.name],['-target','x86_64-windows-gnu','-std=c11','-O2','-Wall','-Wextra','-Werror',
                       f'-I{(SRC/"include").as_posix()}'],SHIM.parent)
        print(shim,file=sys.stderr)
    return 0

SYSTEM_LIBS=['-lsetupapi','-lcfgmgr32','-lole32','-loleaut32','-luuid','-lversion','-limm32','-lwinmm','-luser32',
             '-lgdi32','-ladvapi32','-lshell32']

def link_args():
    """Linker arguments for the runtime DLL: the host-input shim as a whole archive (the runtime references it
    weakly, as libopus, so a DLL linked without it falls back to the keyboard), then libSDL3.a as an ordinary
    archive (only the members the shim pulls in) and the Win32 import libraries SDL needs. Builds if needed."""
    if main()!=0:raise RuntimeError('SDL build failed')
    args=[]
    if SHIM.exists():args+=['-Wl,--whole-archive',str(OUT/'libtotk_input.a'),'-Wl,--no-whole-archive']
    return args+[str(OUT/'libSDL3.a')]+SYSTEM_LIBS

if __name__=='__main__':sys.exit(main())
